import { describe, it, expect, vi } from "vitest";
import type { InspectorStoreState } from "./InspectorStore";
import {
  InspectorView,
  UtteranceType,
  type Conversation,
  type ConversationEvent,
  type Skill,
  type SkillState,
  type Stack,
  type Utterance,
} from "../types";
import {
  selectActiveSkill,
  selectBlockStatus,
  selectConditionResult,
  selectConversationForSelectedElement,
  selectIsMantleEngine,
  selectLatestStack,
  selectReconstructionForSelectedElement,
  selectSkillForSelectedElement,
  selectSkillMemory,
  selectStackToShow,
  selectWaitingForResponse,
} from "./selectors";

const noop = vi.fn();
const asyncNoop = vi.fn().mockResolvedValue(undefined);

function makeState(overrides: Partial<InspectorStoreState> = {}): InspectorStoreState {
  return {
    sessionId: "",
    conversationList: [],
    stack: [],
    inputDisabled: true,
    replayingConversation: false,
    waitingForUserInput: false,
    slots: {},
    slotRelatedEvents: [],
    inspectMode: false,
    inspectorView: InspectorView.ActiveFlow,
    selectedElement: undefined,
    flows: [],
    flowsLoading: false,
    flowsError: null,
    engineType: "calm",
    skillCatalog: null,
    skillState: null,
    lastActiveSkillRef: null,
    projectUrl: "",
    botDataEndpoint: "",
    trackerEndpoint: "",
    conversationEventActions: [],
    voiceFeaturesEnabled: true,
    langfuseEnabled: true,
    isEmbedded: false,
    assistantId: null,
    sendMessage: noop,
    startNewConversation: noop,
    replayConversation: noop,
    startVoiceStreaming: asyncNoop,
    stopVoiceStreaming: asyncNoop,
    onVoiceErrorRef: { current: null },
    ...overrides,
  };
}

function makeStack(overrides: Partial<Stack> = {}): Stack {
  return {
    frameId: "frame-1",
    flowId: "my_flow",
    stepId: "step_1",
    ended: false,
    ...overrides,
  };
}

function makeEvent(overrides: Partial<ConversationEvent> = {}): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    actionText: "",
    conversationEventType: "ACTION" as ConversationEvent["conversationEventType"],
    flowId: "",
    id: overrides.id ?? "evt-1",
    metadata: overrides.metadata ?? { parseData: undefined },
    name: "",
    slotValue: null,
    stepId: "",
    timestamp: new Date().toISOString(),
    ...overrides,
  } as ConversationEvent;
}

function makeConversation(overrides: Partial<Conversation> = {}): Conversation {
  return {
    events: [],
    id: "conv-1",
    reviewed: false,
    startDate: new Date().toISOString(),
    totalNumberOfUserMessages: 0,
    ...overrides,
  };
}

function makeUtterance(overrides: Partial<Utterance> = {}): Utterance {
  return {
    __typename: "Utterance",
    id: overrides.id ?? "utt-1",
    metadata: overrides.metadata ?? { parseData: undefined },
    rephrase: false,
    rephrasePrompt: null,
    text: overrides.text ?? "",
    timestamp: new Date().toISOString(),
    originalTimestamp: Date.now() / 1000,
    tokens: [],
    type: overrides.type ?? UtteranceType.Bot,
    intents: [],
    entities: [],
    ...overrides,
  };
}

// ---------- selectLatestStack ----------

describe("selectLatestStack", () => {
  it("returns undefined for empty stack", () => {
    expect(selectLatestStack(makeState())).toBeUndefined();
  });

  it("returns the last user-visible frame", () => {
    const stack = [
      makeStack({ frameId: "f1", flowId: "greeting" }),
      makeStack({ frameId: "f2", flowId: "farewell" }),
    ];
    const result = selectLatestStack(makeState({ stack }));
    expect(result?.frameId).toBe("f2");
  });

  it("skips internal pattern_ frames", () => {
    const stack = [
      makeStack({ frameId: "f1", flowId: "greeting" }),
      makeStack({ frameId: "f2", flowId: "pattern_internal" }),
    ];
    const result = selectLatestStack(makeState({ stack }));
    expect(result?.frameId).toBe("f1");
  });

  it("allows pattern_session_start", () => {
    const stack = [makeStack({ frameId: "f1", flowId: "pattern_session_start" })];
    expect(selectLatestStack(makeState({ stack }))?.frameId).toBe("f1");
  });

  it("allows pattern_completed", () => {
    const stack = [makeStack({ frameId: "f1", flowId: "pattern_completed" })];
    expect(selectLatestStack(makeState({ stack }))?.frameId).toBe("f1");
  });

  it("allows pattern_user_silence (SWI-1151)", () => {
    const stack = [
      makeStack({ frameId: "f1", flowId: "my_flow" }),
      makeStack({ frameId: "f2", flowId: "pattern_user_silence" }),
    ];
    // pattern_user_silence is visible; f2 should be returned as the latest stack
    expect(selectLatestStack(makeState({ stack }))?.frameId).toBe("f2");
  });

  it("returns undefined when all frames are hidden patterns", () => {
    const stack = [
      makeStack({ flowId: "pattern_collect_information" }),
      makeStack({ flowId: "pattern_correction" }),
    ];
    expect(selectLatestStack(makeState({ stack }))).toBeUndefined();
  });

  it("handles frames with undefined flowId", () => {
    const stack = [makeStack({ flowId: undefined })];
    const result = selectLatestStack(makeState({ stack }));
    expect(result).toBeDefined();
  });
});

// ---------- selectStackToShow ----------

describe("selectStackToShow", () => {
  it("falls back to latestStack when no element is selected", () => {
    const stack = [makeStack({ frameId: "f1", flowId: "my_flow" })];
    const result = selectStackToShow(makeState({ stack }));
    expect(result?.frameId).toBe("f1");
  });

  it("returns selectedElement-based stack when element has flow metadata", () => {
    const selected = makeEvent({
      id: "evt-42",
      metadata: {
        flow_id: "transfer",
        step_id: "ask_amount",
        parseData: undefined,
      },
    });
    const result = selectStackToShow(makeState({ selectedElement: selected, stack: [] }));
    expect(result).toEqual({
      frameId: "evt-42",
      flowId: "transfer",
      stepId: "ask_amount",
      ended: false,
    });
  });

  it("falls back to latestStack when element has no flow_id", () => {
    const selected = makeEvent({
      id: "evt-1",
      metadata: { step_id: "s", parseData: undefined },
    });
    const stack = [makeStack({ frameId: "f1" })];
    const result = selectStackToShow(makeState({ selectedElement: selected, stack }));
    expect(result?.frameId).toBe("f1");
  });

  it("falls back to latestStack when element has no step_id", () => {
    const selected = makeEvent({
      id: "evt-1",
      metadata: { flow_id: "f", parseData: undefined },
    });
    const stack = [makeStack({ frameId: "f1" })];
    const result = selectStackToShow(makeState({ selectedElement: selected, stack }));
    expect(result?.frameId).toBe("f1");
  });

  it("returns undefined when no element and empty stack", () => {
    expect(selectStackToShow(makeState())).toBeUndefined();
  });
});

// ---------- selectConversationForSelectedElement ----------

describe("selectConversationForSelectedElement", () => {
  it("returns undefined when no element is selected", () => {
    expect(selectConversationForSelectedElement(makeState())).toBeUndefined();
  });

  it("returns undefined when element id is not found in any conversation", () => {
    const selected = makeEvent({ id: "missing" });
    const conversations = [
      makeConversation({
        events: [makeEvent({ id: "evt-1" }), makeEvent({ id: "evt-2" })],
      }),
    ];
    expect(
      selectConversationForSelectedElement(
        makeState({
          selectedElement: selected,
          conversationList: conversations,
        }),
      ),
    ).toBeUndefined();
  });

  it("returns the conversation containing the selected element", () => {
    const selected = makeEvent({ id: "evt-2" });
    const target = makeConversation({
      id: "conv-match",
      events: [makeEvent({ id: "evt-2" }), makeEvent({ id: "evt-3" })],
    });
    const other = makeConversation({
      id: "conv-other",
      events: [makeEvent({ id: "evt-99" })],
    });
    const result = selectConversationForSelectedElement(
      makeState({
        selectedElement: selected,
        conversationList: [other, target],
      }),
    );
    expect(result?.id).toBe("conv-match");
  });

  it("returns the first matching conversation when duplicates exist", () => {
    const selected = makeEvent({ id: "evt-shared" });
    const first = makeConversation({
      id: "conv-first",
      events: [makeEvent({ id: "evt-shared" })],
    });
    const second = makeConversation({
      id: "conv-second",
      events: [makeEvent({ id: "evt-shared" })],
    });
    const result = selectConversationForSelectedElement(
      makeState({
        selectedElement: selected,
        conversationList: [first, second],
      }),
    );
    expect(result?.id).toBe("conv-first");
  });
});

// ---------- selectWaitingForResponse ----------

describe("selectWaitingForResponse", () => {
  it("returns true when not waiting for user input and not input disabled", () => {
    expect(
      selectWaitingForResponse(makeState({ waitingForUserInput: false, inputDisabled: false })),
    ).toBe(true);
  });

  it("returns false when waiting for user input", () => {
    expect(
      selectWaitingForResponse(makeState({ waitingForUserInput: true, inputDisabled: false })),
    ).toBe(false);
  });

  it("returns false when input is disabled", () => {
    expect(
      selectWaitingForResponse(makeState({ waitingForUserInput: false, inputDisabled: true })),
    ).toBe(false);
  });

  it("returns false when both waiting for user input and input disabled", () => {
    expect(
      selectWaitingForResponse(makeState({ waitingForUserInput: true, inputDisabled: true })),
    ).toBe(false);
  });

  it("returns false when last utterance is a non-empty bot message", () => {
    const botUtterance = makeUtterance({
      id: "utt-bot",
      type: UtteranceType.Bot,
      text: "This is complete",
    });
    const conversation = makeConversation({
      events: [botUtterance],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(false);
  });

  it("returns false when last bot utterance has a single character of text", () => {
    const userUtterance = makeUtterance({
      id: "utt-user",
      type: UtteranceType.User,
      text: "Hello",
    });
    const botUtterance = makeUtterance({
      id: "utt-bot",
      type: UtteranceType.Bot,
      text: "H",
    });
    const conversation = makeConversation({
      events: [userUtterance, botUtterance],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(false);
  });

  it("returns false when bot utterance exists before action_listen arrives", () => {
    const userUtterance = makeUtterance({
      id: "utt-user",
      type: UtteranceType.User,
      text: "/session_start",
    });
    const botUtterance = makeUtterance({
      id: "utt-bot",
      type: UtteranceType.Bot,
      text: "Hi there! I'm Riley 👋.",
    });
    const conversation = makeConversation({
      events: [userUtterance, botUtterance],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(false);
  });

  it("returns false when bot utterance has buttons but no text", () => {
    const userUtterance = makeUtterance({
      id: "utt-user",
      type: UtteranceType.User,
      text: "Pick one",
    });
    const botUtterance = makeUtterance({
      id: "utt-bot",
      type: UtteranceType.Bot,
      text: "",
      responseData: {
        buttons: [{ title: "Option A", payload: "a" }],
        quickReplies: [],
      },
    });
    const conversation = makeConversation({
      events: [userUtterance, botUtterance],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(false);
  });

  it("returns true when last utterance is from the user", () => {
    const userUtterance = makeUtterance({
      id: "utt-user",
      type: UtteranceType.User,
      text: "Hello",
    });
    const conversation = makeConversation({
      events: [userUtterance],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(true);
  });

  it("returns true when user sent a follow-up after the bot replied", () => {
    const firstUser = makeUtterance({
      id: "utt-user-1",
      type: UtteranceType.User,
      text: "Hello",
    });
    const botUtterance = makeUtterance({
      id: "utt-bot",
      type: UtteranceType.Bot,
      text: "Hi there!",
    });
    const followUpUser = makeUtterance({
      id: "utt-user-2",
      type: UtteranceType.User,
      text: "Tell me more",
    });
    const conversation = makeConversation({
      events: [firstUser, botUtterance, followUpUser],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(true);
  });

  it("returns true when last bot utterance is empty", () => {
    const userUtterance = makeUtterance({
      id: "utt-user",
      type: UtteranceType.User,
      text: "Hello",
    });
    const emptyBotUtterance = makeUtterance({
      id: "utt-bot-empty",
      type: UtteranceType.Bot,
      text: "",
    });
    const conversation = makeConversation({
      events: [userUtterance, emptyBotUtterance],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(true);
  });

  it("returns true when conversation list is empty", () => {
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [],
        }),
      ),
    ).toBe(true);
  });

  it("returns false when last utterance is bot even if non-utterance events follow", () => {
    const userUtterance = makeUtterance({
      id: "utt-user",
      type: UtteranceType.User,
      text: "Hello",
    });
    const botUtterance = makeUtterance({
      id: "utt-bot",
      type: UtteranceType.Bot,
      text: "Replying...",
    });
    const conversation = makeConversation({
      events: [userUtterance, botUtterance, makeEvent({ id: "evt-1" })],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [conversation],
        }),
      ),
    ).toBe(false);
  });

  it("checks only the last conversation for the latest utterance", () => {
    const oldConversation = makeConversation({
      id: "conv-old",
      events: [
        makeUtterance({
          id: "utt-old-user",
          type: UtteranceType.User,
          text: "Old question",
        }),
        makeUtterance({
          id: "utt-old-bot",
          type: UtteranceType.Bot,
          text: "Old answer",
        }),
      ],
    });
    const newConversationWaiting = makeConversation({
      id: "conv-new-waiting",
      events: [
        makeUtterance({
          id: "utt-new-user",
          type: UtteranceType.User,
          text: "New question",
        }),
      ],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [oldConversation, newConversationWaiting],
        }),
      ),
    ).toBe(true);

    const newConversationAnswered = makeConversation({
      id: "conv-new-answered",
      events: [
        makeUtterance({
          id: "utt-new-user-2",
          type: UtteranceType.User,
          text: "New question",
        }),
        makeUtterance({
          id: "utt-new-bot",
          type: UtteranceType.Bot,
          text: "New answer",
        }),
      ],
    });
    expect(
      selectWaitingForResponse(
        makeState({
          waitingForUserInput: false,
          inputDisabled: false,
          conversationList: [oldConversation, newConversationAnswered],
        }),
      ),
    ).toBe(false);
  });
});

describe("skill-mode selectors", () => {
  const cardReplace: Skill = {
    id: "card_replace",
    name: "Card Replace",
    description: "Replace a card.",
    is_default: false,
    engine_managed: false,
    disabled: false,
    sections: [
      { type: "prose", segments: [{ text: "Help the customer.", condition: null }] },
      { type: "ordered_block", block_id: "main" },
    ],
    blocks: {
      main: {
        ordered_block_id: "card_replace__main",
        complete_when: null,
        steps: [{ id: "start", kind: "action" }],
      },
    },
    referenced_skills: [],
    tool_names: ["lock_card"],
    hidden: false,
  };

  const skillState: SkillState = {
    active_skill: {
      skill_id: "card_replace",
      ordered_block_id: "card_replace__main",
      step_id: "start",
    },
    blocks: { card_replace__main: { status: "active" } },
    evaluated_conditions: { "session.card_replace.ready": true },
    tools: {},
    llm_calls: [],
    memory: {
      "card_replace.reason": { value: "lost", source: "llm", scope: "skill", description: null },
    },
    pending_skills: [],
  };

  it("detects skill mode from the declared engine, not the catalog", () => {
    expect(selectIsMantleEngine(makeState())).toBe(false);
    // A populated catalog alone does not flip the mode — the engine flag does.
    expect(selectIsMantleEngine(makeState({ skillCatalog: { card_replace: cardReplace } }))).toBe(
      false,
    );
    expect(selectIsMantleEngine(makeState({ engineType: "mantle" }))).toBe(true);
  });

  it("joins the active skill ref with its catalog entry", () => {
    const state = makeState({ skillCatalog: { card_replace: cardReplace }, skillState });
    expect(selectActiveSkill(state)).toEqual({
      skill: cardReplace,
      flowId: "card_replace__main",
      stepId: "start",
    });
  });

  it("returns undefined when the active ref carries no skill id", () => {
    const state = makeState({
      skillCatalog: { card_replace: cardReplace },
      skillState: {
        ...skillState,
        active_skill: { skill_id: null, ordered_block_id: "card_replace__main", step_id: null },
      },
    });
    expect(selectActiveSkill(state)).toBeUndefined();
  });

  it("returns undefined when the stamped skill id is absent from the catalog", () => {
    const state = makeState({
      skillCatalog: { card_replace: cardReplace },
      skillState: {
        ...skillState,
        active_skill: {
          skill_id: "missing_skill",
          ordered_block_id: "card_replace__main",
          step_id: null,
        },
      },
    });
    expect(selectActiveSkill(state)).toBeUndefined();
  });

  it("returns undefined while routing or in flow mode", () => {
    expect(selectActiveSkill(makeState())).toBeUndefined();
    const routing = makeState({
      skillCatalog: { card_replace: cardReplace },
      skillState: { ...skillState, active_skill: null },
    });
    expect(selectActiveSkill(routing)).toBeUndefined();
  });

  it("reports block status with an inactive default", () => {
    const state = makeState({ skillState });
    expect(selectBlockStatus(state, "card_replace__main")).toBe("active");
    expect(selectBlockStatus(state, "card_replace__other")).toBe("inactive");
    expect(selectBlockStatus(makeState(), "card_replace__main")).toBe("inactive");
  });

  it("exposes condition results and memory", () => {
    const state = makeState({ skillState });
    expect(selectConditionResult(state, "session.card_replace.ready")).toBe(true);
    expect(selectConditionResult(state, "session.card_replace.unknown")).toBeUndefined();
    expect(selectSkillMemory(state)?.["card_replace.reason"]?.source).toBe("llm");
    expect(selectSkillMemory(makeState())).toBeUndefined();
  });

  it("keeps showing the last active skill between skills via the ref fallback", () => {
    const state = makeState({
      skillCatalog: { card_replace: cardReplace },
      skillState: { ...skillState, active_skill: null },
      lastActiveSkillRef: {
        skill_id: "card_replace",
        ordered_block_id: "card_replace__main",
        step_id: null,
      },
    });
    expect(selectActiveSkill(state)?.skill.id).toBe("card_replace");
  });

  describe("selectSkillForSelectedElement", () => {
    const transfer: Skill = {
      ...cardReplace,
      id: "transfer",
      name: "Transfer",
      blocks: {
        main: {
          ordered_block_id: "transfer__main",
          complete_when: null,
          steps: [{ id: "ask_amount", kind: "collect" }],
        },
      },
      referenced_skills: [],
      tool_names: [],
    };
    const catalog = { card_replace: cardReplace, transfer };
    const liveSkillState: SkillState = {
      ...skillState,
      active_skill: {
        skill_id: "transfer",
        ordered_block_id: "transfer__main",
        step_id: "ask_amount",
      },
    };

    it("returns the live active skill when nothing is selected", () => {
      const state = makeState({ skillCatalog: catalog, skillState: liveSkillState });
      expect(selectSkillForSelectedElement(state)?.skill.id).toBe("transfer");
    });

    it("resolves the skill active at the selected message from its stamped skill id", () => {
      const selected = makeEvent({
        id: "evt-9",
        skillId: "card_replace",
        metadata: { flow_id: "card_replace__main", step_id: "start", parseData: undefined },
      });
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
      });
      const result = selectSkillForSelectedElement(state);
      expect(result?.skill.id).toBe("card_replace");
      expect(result?.stepId).toBe("start");
    });

    it("reads the skill id from a memory write's provenance", () => {
      const selected = makeEvent({
        id: "evt-10",
        metadata: {
          flow_id: "card_replace__main",
          step_id: "start",
          parseData: undefined,
          mantle_write_provenance: { skill_id: "card_replace" },
        },
      });
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
      });
      expect(selectSkillForSelectedElement(state)?.skill.id).toBe("card_replace");
    });

    it("falls back to the live active skill when the selected flow id is unknown", () => {
      const selected = makeEvent({
        id: "evt-11",
        skillId: "card_replace",
        metadata: { flow_id: "pattern_completed", step_id: "s", parseData: undefined },
      });
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
      });
      // flow_id resolves the step, but here it is a pattern flow; the stamped id
      // still resolves the skill, so we keep showing card_replace.
      expect(selectSkillForSelectedElement(state)?.skill.id).toBe("card_replace");
    });

    it("shows the empty state (not the live skill) when nothing skill-stamped precedes the selection", () => {
      const selected = makeEvent({
        id: "evt-12",
        metadata: { flow_id: "shared__block", step_id: "start", parseData: undefined },
      });
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
      });
      // No stamped id and no skill-stamped event before it → no skill was active
      // then; the pane shows its empty state rather than the live skill.
      expect(selectSkillForSelectedElement(state)).toBeUndefined();
    });

    it("anchors a chat message to the nearest preceding skill-stamped event", () => {
      const selected = makeUtterance({ id: "msg-1", type: UtteranceType.User });
      const conversations = [
        makeConversation({
          events: [
            makeEvent({
              id: "evt-a",
              skillId: "card_replace",
              metadata: { flow_id: "card_replace__main", step_id: "start", parseData: undefined },
            }),
            selected,
            makeEvent({
              id: "evt-b",
              skillId: "transfer",
              metadata: { flow_id: "transfer__main", step_id: "ask_amount", parseData: undefined },
            }),
          ],
        }),
      ];
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
        conversationList: conversations,
      });
      // The message itself carries no skill scope; the skill at that moment is
      // the one whose stamped event last ran BEFORE it — never a later one.
      const result = selectSkillForSelectedElement(state);
      expect(result?.skill.id).toBe("card_replace");
      expect(result?.stepId).toBe("start");
    });

    it("anchors on a real-shaped skill event that carries no flow scope", () => {
      // The engine's SkillActivated has only a skill id — no flow_id anywhere.
      const selected = makeUtterance({ id: "msg-3", type: UtteranceType.User });
      const conversations = [
        makeConversation({
          events: [
            makeEvent({
              id: "evt-activated",
              conversationEventType:
                "SKILL_ACTIVATED" as ConversationEvent["conversationEventType"],
              skillId: "card_replace",
              metadata: { parseData: undefined },
            }),
            selected,
          ],
        }),
      ];
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
        conversationList: conversations,
      });
      const result = selectSkillForSelectedElement(state);
      // The document still time-travels; there is just no step to highlight.
      expect(result?.skill.id).toBe("card_replace");
      expect(result?.flowId).toBeNull();
      expect(result?.stepId).toBeNull();
    });

    it("reads the flow scope from a memory event's top-level flowId", () => {
      // memory_set maps its flow onto the event's flowId field, not metadata.
      const selected = makeUtterance({ id: "msg-4", type: UtteranceType.User });
      const conversations = [
        makeConversation({
          events: [
            makeEvent({
              id: "evt-write",
              conversationEventType: "MEMORY_SET" as ConversationEvent["conversationEventType"],
              flowId: "card_replace__main",
              stepId: "collect_reason",
              metadata: {
                parseData: undefined,
                mantle_write_provenance: { skill_id: "card_replace" },
              },
            }),
            selected,
          ],
        }),
      ];
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
        conversationList: conversations,
      });
      const result = selectSkillForSelectedElement(state);
      expect(result?.skill.id).toBe("card_replace");
      expect(result?.flowId).toBe("card_replace__main");
      expect(result?.stepId).toBe("collect_reason");
    });

    it("shows the empty state for a message before any skill event (not the live skill)", () => {
      const selected = makeUtterance({ id: "msg-0", type: UtteranceType.User });
      const conversations = [
        makeConversation({
          events: [
            selected,
            makeEvent({
              id: "evt-later",
              skillId: "card_replace",
              metadata: { flow_id: "card_replace__main", step_id: "start", parseData: undefined },
            }),
          ],
        }),
      ];
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: selected,
        conversationList: conversations,
      });
      // The selection precedes any skill activity: nothing was active then, so
      // the pane shows its empty state — it never reverts to the live skill
      // while a selection stands.
      expect(selectSkillForSelectedElement(state)).toBeUndefined();
    });

    it("travels from a synthesized LLM-call row not present in conversationList", () => {
      // ChatSection merges llm_calls into the display list only; the row's id is
      // absent from conversationList, so the anchor is found by its timestamp.
      const skillEvent = makeEvent({
        id: "evt-skill",
        skillId: "card_replace",
        metadata: { flow_id: "card_replace__main", step_id: "start", parseData: undefined },
      });
      skillEvent.originalTimestamp = 100;
      const laterUser = makeUtterance({ id: "msg-later", type: UtteranceType.User });
      laterUser.originalTimestamp = 300;
      const llmRow = {
        ...makeEvent({ id: "llm-call-abc" }),
        conversationEventType: "LLM_CALL_RECORDED" as ConversationEvent["conversationEventType"],
        originalTimestamp: 200,
      };
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveSkillState,
        selectedElement: llmRow,
        conversationList: [makeConversation({ events: [skillEvent, laterUser] })],
      });
      // The LLM row sits between the skill event and the later user message, so
      // it anchors on the skill event that ran before it.
      expect(selectSkillForSelectedElement(state)?.skill.id).toBe("card_replace");
    });

    it("returns undefined when the selected flow is unknown and no skill is live", () => {
      const selected = makeEvent({
        id: "evt-13",
        metadata: { flow_id: "pattern_completed", step_id: "s", parseData: undefined },
      });
      const state = makeState({
        skillCatalog: catalog,
        skillState: { ...liveSkillState, active_skill: null },
        selectedElement: selected,
      });
      expect(selectSkillForSelectedElement(state)).toBeUndefined();
    });
  });

  describe("selectReconstructionForSelectedElement", () => {
    const catalog = { card_replace: cardReplace };
    const liveState: SkillState = {
      ...skillState,
      active_skill: {
        skill_id: "card_replace",
        ordered_block_id: "card_replace__main",
        step_id: "start",
      },
    };

    it("returns undefined when nothing is selected", () => {
      expect(
        selectReconstructionForSelectedElement(
          makeState({ skillCatalog: catalog, skillState: liveState }),
        ),
      ).toBeUndefined();
    });

    it("returns the conversation events, anchor index and skill id for a selection", () => {
      const skillEvent = makeEvent({
        id: "evt-skill",
        skillId: "card_replace",
        metadata: { flow_id: "card_replace__main", step_id: "start", parseData: undefined },
      });
      const selected = makeUtterance({ id: "msg-1", type: UtteranceType.User });
      const conversation = makeConversation({ events: [skillEvent, selected] });
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveState,
        selectedElement: selected,
        conversationList: [conversation],
      });
      const result = selectReconstructionForSelectedElement(state);
      expect(result?.anchoredSkillId).toBe("card_replace");
      expect(result?.anchorIndex).toBe(1);
      expect(result?.events).toBe(conversation.events);
    });

    it("returns undefined when the selection precedes any skill activity", () => {
      const selected = makeUtterance({ id: "msg-0", type: UtteranceType.User });
      const conversation = makeConversation({ events: [selected] });
      const state = makeState({
        skillCatalog: catalog,
        skillState: liveState,
        selectedElement: selected,
        conversationList: [conversation],
      });
      expect(selectReconstructionForSelectedElement(state)).toBeUndefined();
    });
  });
});
